class DBError(Exception):
    def __init__(self, pgcode):
        super().__init__(pgcode)
        self.pgcode = pgcode

outcomes = iter(["40P01", "40P01", None])

def transaction():
    code = next(outcomes)
    if code:
        raise DBError(code)
    return "committed"

def run_in_tx(fn, attempts=3):
    for attempt in range(1, attempts + 1):
        try:
            return fn(), attempt
        except DBError as e:
            print(f"attempt {attempt}: {e.pgcode}, rollback")
            if e.pgcode != "40P01" or attempt == attempts:
                raise

