def apply_stock_changes(conn, changes: dict[str, int]):
    # changes comes from a DataFrame groupby, order varies per file
    with conn.cursor() as cur:
        for sku, delta in changes.items():
            cur.execute("UPDATE inventory SET qty = qty + %s WHERE sku = %s", (delta, sku))
    conn.commit()
